UPDATE area a SET qty = a.qty - o.order_qty FROM ( VALUES
(#{order.eventsId}, #{order.orderArea}, #{order.orderQty})
) AS o(events_id, area_name, order_qty) WHERE a.events_id = o.events_id AND a.area_name = o.area_name AND a.qty >= o.order_qty;

UPDATE area a SET qty = a.qty + o.order_qty FROM (
SELECT #{order.eventsId} AS events_id, #{order.orderArea} AS area_name, #{order.orderQty} AS order_qty
) o(events_id, area_name, order_qty) WHERE a.events_id = o.events_id AND a.area_name = o.area_name
